{
  "body": "if (!validateRecord(record)) {
  return { ok: false, error: 'INVALID_RECORD' };
}
if (!Number.isSafeInteger(now) || now < 0) {
  return { ok: false, error: 'INVALID_CLOCK' };
}
if (typeof event !== 'object' || event === null || Array.isArray(event)) {
  return { ok: false, error: 'INVALID_TRANSITION' };
}
const eventKeys = Object.keys(event);
if (eventKeys.length !== 1) {
  return { ok: false, error: 'INVALID_TRANSITION' };
}
const type = event.type;
if (type === 'CONFIGURE') {
  if (record.phase !== 'ready' && record.phase !== 'completed') {
    return { ok: false, error: 'INVALID_TRANSITION' };
  }
  if (eventKeys[0] !== 'minutes') {
    return { ok: false, error: 'INVALID_TRANSITION' };
  }
  const minutes = event.minutes;
  if (!Number.isSafeInteger(minutes) || minutes < 1 || minutes > 180) {
    return { ok: false, error: 'INVALID_TRANSITION' };
  }
  return {
    ok: true,
    record: {
      version: 1,
      durationMinutes: minutes,
      phase: 'ready',
      remainingMs: minutes * 60000,
      runStartedAt: null,
      deadlineAt: null
    }
  };
}
if (type === 'START') {
  if (record.phase !== 'ready' && record.phase !== 'completed') {
    return { ok: false, error: 'INVALID_TRANSITION' };
  }
  const startAt = now;
  const deadline = startAt + record.remainingMs;
  if (!Number.isSafeInteger(deadline)) {
    return { ok: false, error: 'INVALID_CLOCK' };
  }
  return {
    ok: true,
    record: {
      version: 1,
      durationMinutes: record.durationMinutes,
      phase: 'running',
      remainingMs: record.remainingMs,
      runStartedAt: startAt,
      deadlineAt: deadline
    }
  };
}
if (type === 'PAUSE') {
  if (record.phase !== 'running') {
    return { ok: false, error: 'INVALID_TRANSITION' };
  }
  const elapsed = now - record.runStartedAt;
  const remaining = Math.max(0, record.remainingMs - elapsed);
  if (remaining === 0) {
    return { ok: false, error: 'INVALID_TRANSITION' };
  }
  return {
    ok: true,
    record: {
      version: 1,
      durationMinutes: record.durationMinutes,
      phase: 'paused',
      remainingMs: remaining,
      runStartedAt: null,
      deadlineAt: null
    }
  };
}
if (type === 'RESUME') {
  if (record.phase !== 'paused') {
    return { ok: false, error: 'INVALID_TRANSITION' };
  }
  const startAt = now;
  const deadline = startAt + record.remainingMs;
  if (!Number.isSafeInteger(deadline)) {
    return { ok: false, error: 'INVALID_CLOCK' };
  }
  return {
    ok: true,
    record: {
      version: 1,
      durationMinutes: record.durationMinutes,
      phase: 'running',
      remainingMs: record.remainingMs,
      runStartedAt: startAt,
      deadlineAt: deadline
    }
  };
}
if (type === 'RESET') {
  const fullDuration = record.durationMinutes * 60000;
  return {
    ok: true,
    record: {
      version: 1,
      durationMinutes: record.durationMinutes,
      phase: 'ready',
      remainingMs: fullDuration,
      runStartedAt: null,
      deadlineAt: null
    }
  };
}
return { ok: false, error: 'INVALID_TRANSITION' };"
}
